Here is the commit message:
iio: adc: imx25-gcq: Fix leak of device_node in
 mx25_gcq_setup_cfgs()

Leaving for_each_child_of_node loop we should release child device node,
if it is not stored for future use.

Found by Linux Driver Verification project (linuxtesting.org).

JC: I'm not sending this as a quick fix as it's been wrong for years,
but good to pick up for stable after the merge window.

Signed-off-by: Alexey Khoroshilov <khoroshilov@ispras.ru>
Fixes: 6df2e98c3ea56 ("iio: adc: Add imx25-gcq ADC driver")
Cc: <Stable@vger.kernel.org>
Signed-off-by: Jonathan Cameron <Jonathan.Cameron@huawei.com>

Here is the root cause:
The bug is caused by the failure to release the child device node in the `mx25_gcq_setup_cfgs` function when certain error conditions are encountered. This oversight leads to a memory leak, as the allocated device node remains unfreed if it is not stored for future use.

Here is the patch:

 static int mx25_gcq_setup_cfgs(struct platform_device *pdev,
 			       struct mx25_gcq_priv *priv)
 {
 	struct device_node *np = pdev->dev.of_node;
 	struct device_node *child;
 	struct device *dev = &pdev->dev;
 	unsigned int refp_used[4] = {};
 	int ret, i;

 	/*
 	 * Setup all configurations registers with a default conversion
 	 * configuration for each input
 	 */
 	for (i = 0; i < MX25_NUM_CFGS; ++i)
 		regmap_write(priv->regs, MX25_ADCQ_CFG(i),
 			     MX25_ADCQ_CFG_YPLL_OFF |
 			     MX25_ADCQ_CFG_XNUR_OFF |
 			     MX25_ADCQ_CFG_XPUL_OFF |
 			     MX25_ADCQ_CFG_REFP_INT |
 			     MX25_ADCQ_CFG_IN(i) |
 			     MX25_ADCQ_CFG_REFN_NGND2);

 	/*
 	 * First get all regulators to store them in channel_vref_mv if
 	 * necessary. Later we use that information for proper IIO scale
 	 * information.
 	 */
 	priv->vref[MX25_ADC_REFP_INT] = NULL;
 	priv->vref[MX25_ADC_REFP_EXT] =
 		devm_regulator_get_optional(&pdev->dev, "vref-ext");
 	priv->vref[MX25_ADC_REFP_XP] =
 		devm_regulator_get_optional(&pdev->dev, "vref-xp");
 	priv->vref[MX25_ADC_REFP_YP] =
 		devm_regulator_get_optional(&pdev->dev, "vref-yp");

 	for_each_child_of_node(np, child) {
 		u32 reg;
 		u32 refp = MX25_ADCQ_CFG_REFP_INT;
 		u32 refn = MX25_ADCQ_CFG_REFN_NGND2;

 		ret = of_property_read_u32(child, "reg", &reg);
 		if (ret) {
 			dev_err(dev, "Failed to get reg property\n");
+			of_node_put(child);
 			return ret;
 		}

 		if (reg >= MX25_NUM_CFGS) {
 			dev_err(dev,
 				"reg value is greater than the number of available configuration registers\n");
+			of_node_put(child);
 			return -EINVAL;
 		}

 		of_property_read_u32(child, "fsl,adc-refp", &refp);
 		of_property_read_u32(child, "fsl,adc-refn", &refn);

 		switch (refp) {
 		case MX25_ADC_REFP_EXT:
 		case MX25_ADC_REFP_XP:
 		case MX25_ADC_REFP_YP:
 			if (IS_ERR(priv->vref[refp])) {
 				dev_err(dev, "Error, trying to use external voltage reference without a vref-%s regulator.",
 					mx25_gcq_refp_names[refp]);
+				of_node_put(child);
 				return PTR_ERR(priv->vref[refp]);
 			}
 			priv->channel_vref_mv[reg] =
 				regulator_get_voltage(priv->vref[refp]);
 			/* Conversion from uV to mV */
 			priv->channel_vref_mv[reg] /= 1000;
 			break;
 		case MX25_ADC_REFP_INT:
 			priv->channel_vref_mv[reg] = 2500;
 			break;
 		default:
 			dev_err(dev, "Invalid positive reference %d\n", refp);
+			of_node_put(child);
 			return -EINVAL;
 		}

 		++refp_used[refp];

 		/*
 		 * Shift the read values to the correct positions within the
 		 * register.
 		 */
 		refp = MX25_ADCQ_CFG_REFP(refp);
 		refn = MX25_ADCQ_CFG_REFN(refn);

 		if ((refp & MX25_ADCQ_CFG_REFP_MASK) != refp) {
 			dev_err(dev, "Invalid fsl,adc-refp property value\n");
+			of_node_put(child);
 			return -EINVAL;
 		}
 		if ((refn & MX25_ADCQ_CFG_REFN_MASK) != refn) {
 			dev_err(dev, "Invalid fsl,adc-refn property value\n");
+			of_node_put(child);
 			return -EINVAL;
 		}

 		regmap_update_bits(priv->regs, MX25_ADCQ_CFG(reg),
 				   MX25_ADCQ_CFG_REFP_MASK |
 				   MX25_ADCQ_CFG_REFN_MASK,
 				   refp | refn);
 	}
 	regmap_update_bits(priv->regs, MX25_ADCQ_CR,
 			   MX25_ADCQ_CR_FRST | MX25_ADCQ_CR_QRST,
 			   MX25_ADCQ_CR_FRST | MX25_ADCQ_CR_QRST);

 	regmap_write(priv->regs, MX25_ADCQ_CR,
 		     MX25_ADCQ_CR_PDMSK | MX25_ADCQ_CR_QSM_FQS);

 	/* Remove unused regulators */
 	for (i = 0; i != 4; ++i) {
 		if (!refp_used[i]) {
 			if (!IS_ERR_OR_NULL(priv->vref[i]))
 				devm_regulator_put(priv->vref[i]);
 			priv->vref[i] = NULL;
 		}
 	}

 	return 0;
 }



